def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent moves and compute scores.
    my_score = 0
    op_score = 0
    op_c = 0
    op_d = 0
    last_my, last_op = history[-1]
    for me, opp in history:
        if opp == 'C':
            op_c += 1
        else:
            op_d += 1
        if me == 'C' and opp == 'C':
            my_score += 3
            op_score += 3
        elif me == 'C' and opp == 'D':
            op_score += 5
        elif me == 'D' and opp == 'C':
            my_score += 5
        else:
            my_score += 1
            op_score += 1

    # Always defect against a confirmed all-defector.
    if op_c == 0:
        return 'D'

    # Cooperate with a confirmed all-cooperator, but take a few late-game opportunities.
    if op_d == 0:
        if n >= 96 and rng.random() < 0.5:
            return 'D'
        if n >= 85 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Recent opponent behavior.
    window = history[-8:] if n >= 8 else history
    rec_c = sum(1 for me, opp in window if opp == 'C')
    rec_len = len(window)
    rec_d = rec_len - rec_c

    # Opponent defected last round: retaliate, but forgive if they are mostly cooperative.
    if last_op == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        if op_c > op_d * 2 and rng.random() < 0.35:
            return 'C'
        if op_c > op_d and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we just defected, return toward cooperation unless opponent is dangerous.
    if last_my == 'D':
        if op_d * 2 > op_c and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Punish clusters of defection.
    if rec_d >= 4:
        return 'D'
    if rec_d >= 3 and rng.random() < 0.7:
        return 'D'
    if op_c < op_d and n > 4:
        if rng.random() < 0.5:
            return 'D'

    # Occasionally exploit an opponent that is very cooperative.
    if op_c * 10 >= n * 9 and n >= 12:
        if rng.random() < 0.08:
            return 'D'

    # If far behind, try to catch up with a moderate defection.
    if my_score + 8 < op_score and n >= 5:
        if rng.random() < 0.25:
            return 'D'

    return 'C'
